ttom:14px}.section-head h2{margin:0;font-size:20px}.section-head p{margin:4px 0 0;color:#64748b;font-size:12px}.btn{border:0;border-radius:11px;padding:10px 14px;min-height:42px;font-weight:800;cursor:pointer;display:inline-flex;align-items:center;justify-content:center;text-decoration:none;transition:.15s ease}.btn:hover{transform:translateY(-1px)}.primary{background:#2563eb;color:#fff}.success{background:#16a34a;color:#fff}.warning{background:#f59e0b;color:#fff}.danger{background:#fff1f2;color:#be123c;border:1px solid #fecdd3}.secondary{background:#eef2ff;color:#3730a3}.neutral{background:#f1f5f9;color:#334155}.toolbar{display:flex;gap:8px;flex-wrap:wrap}.field{margin-bottom:12px}.field label{display:block;font-size:11px;font-weight:800;color:#475569;margin-bottom:6px;text-transform:uppercase;letter-spacing:.03em}.field input,.field select{width:100%;border:1px solid #cbd5e1;border-radius:11px;padding:10px 11px;background:#fff;font-size:13px}.field input:focus,.field select:focus{outline:none;border-color:#6366f1;box-shadow:0 0 0 3px rgba(99,102,241,.12)}.status{padding:11px 12px;border-radius:11px;background:#f8fafc;border:1px solid var(--line);font-size:12px;color:#475569;white-space:pre-wrap}.status.ok{background:#ecfdf5;border-color:#a7f3d0;color:#047857}.status.err{background:#fff1f2;border-color:#fecdd3;color:#be123c}.status.warn{background:#fffbeb;border-color:#fde68a;color:#92400e}.table-wrap{overflow:auto}.table{width:100%;border-collapse:collapse;font-size:12px}.table th{background:#f8fafc;color:#64748b;text-align:left;padding:10px;border-bottom:1px solid var(--line);white-space:nowrap}.table td{padding:10px;border-bottom:1px solid #f1f5f9;vertical-align:top}.table tr:hover td{background:#fafcff}.pill{display:inline-flex;padding:4px 8px;border-radius:999px;font-size:10px;font-weight:800;background:#eef2ff;color:#4338ca}.pill.green{background:#ecfdf5;color:#047857}.pill.red{background:#fff1f2;color:#be123c}.pill.gray{background:#f1f5f9;color:#475569}.two{grid-template-columns:1fr 1fr}.three{grid-template-columns:repeat(3,minmax(0,1fr))}.school-grid,.claim-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.school{border:1px solid #dbeafe;border-radius:16px;padding:15px;background:linear-gradient(180deg,#fff,#f8fbff)}.school h3{margin:0;font-size:15px}.school p{margin:4px 0;color:#64748b;font-size:11px}.school .metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:6px;margin:12px 0}.school .metrics div{background:#fff;border:1px solid #e2e8f0;border-radius:10px;padding:7px;text-align:center}.school .metrics b{display:block;font-size:16px}.school .metrics span{font-size:9px;color:#64748b}.modal{position:fixed;inset:0;background:rgba(15,23,42,.55);display:none;align-items:flex-start;justify-content:center;padding:30px 16px;z-index:30;overflow:auto}.modal.open{display:flex}.modal-panel{width:min(1180px,100%);background:#fff;border-radius:20px;box-shadow:0 30px 90px rgba(15,23,42,.3);padding:20px}.tabs{display:flex;gap:6px;flex-wrap:wrap;margin:12px 0}.tabs button{border:1px solid #e2e8f0;background:#fff;padding:8px 10px;border-radius:9px;font-weight:700;cursor:pointer}.tabs button.active{background:#eef2ff;color:#3730a3;border-color:#c7d2fe}.subpanel{display:none}.subpanel.active{display:block}.claim{border:1px solid #e2e8f0;border-radius:14px;padding:14px;background:#fff}.claim h3{margin:0;font-size:14px}.claim p{margin:4px 0;color:#64748b;font-size:11px}.meta{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:6px;margin:9px 0}.meta div{background:#f8fafc;border-radius:9px;padding:8px;font-size:11px}.output{background:#0f172a;color:#dbeafe;border-radius:14px;padding:14px;font:12px/1.55 Consolas,monospace;white-space:pre-wrap;max-height:440px;overflow:auto}.keybox{background:#111827;color:#fff;padding:14px;border-radius:14px;margin-top:10px}.keybox code{display:block;font-size:15px;word-break:break-all;color:#a5f3fc}.muted{color:#64748b;font-size:12px;line-height:1.6}.danger-zone{border-color:#fecaca;background:#fffafa}@media(max-width:1050px){.app{grid-template-columns:1fr}.side{position:relative;height:auto}.nav{grid-template-columns:repeat(4,1fr)}.stats{grid-template-columns:repeat(2,1fr)}}@media(max-width:700px){.main{padding:14px}.topbar{align-items:flex-start;flex-direction:column}.connect{width:100%;flex-direction:column;align-items:stretch}.connect input{width:100%}.stats,.two,.three,.school-grid,.claim-grid{grid-template-columns:1fr}.nav{grid-template-columns:repeat(2,1fr)}}
