</div><div class="side-foot">Aplikasi lokal khusus Admin Pusat.<br>Master key tidak disimpan ke disk/browser storage.<br>Jangan masukkan panel ini ke paket sekolah/GTK.</div></aside>
<main class="main">
<div class="topbar"><div><h1 id="pageTitle">Dasbor Pusat</h1><p id="pageDesc">Status terpusat eduXid Cloud dan instalasi pusat.</p></div><div class="connect"><input id="masterKey" type="password" autocomplete="off" placeholder="Master EDUXID_ADMIN_KEY"><button class="btn primary" id="connectBtn">Hubungkan</button></div></div>
<div id="globalStatus" class="status">Belum terhubung ke eduXid Cloud.</div>

<section id="dashboard" class="section active" style="margin-top:14px"><div class="grid stats" id="stats"></div><div class="grid two" style="margin-top:14px"><div class="card"><div class="section-head"><div><h2>Cloud Pusat</h2><p>Ringkasan operasional dari Worker dan D1.</p></div><button class="btn secondary" onclick="refreshAll()">Muat Ulang</button></div><div id="cloudSummary" class="status">Hubungkan Master Key untuk memuat data.</div></div><div class="card"><div class="section-head"><div><h2>Instalasi Lokal</h2><p>Deteksi komponen di root eduXidMaster.</p></div></div><div id="localSummary" class="status">Memeriksa…</div></div></div></section>

<section id="schools" class="section" style="margin-top:14px"><div class="section-head"><div><h2>Sekolah & Akun Cloud</h2><p>Kelola sekolah, GTK, siswa, perangkat, dan status sinkronisasi.</p></div><button class="btn secondary" onclick="loadSchools()">Muat Ulang</button></div><div id="schoolsGrid" class="school-grid"></div></section>

<section id="keys" class="section" style="margin-top:14px"><div class="grid two"><div class="card"><h2 style="margin-top:0">Buat Kunci Cloud Sekolah</h2><div class="field"><label>NPSN / School ID</label><input id="keySchool" placeholder="Contoh 30102991"></div><div class="field"><label>Nama Sekolah / Label</label><input id="keyLabel" placeholder="Nama sekolah"></div><button class="btn primary" onclick="createSchoolKey()">Buat Key Pair</button><div id="newKeyBox"></div></div><div class="card"><div class="section-head"><div><h2>Daftar Kunci Sekolah</h2><p>Plaintext token tidak disimpan Cloud; hanya muncul sekali saat dibuat.</p></div><button class="btn secondary" onclick="loadKeys()">Muat Ulang</button></div><div id="keysTable"></div></div></div></section>

<section id="donation" class="section" style="margin-top:14px"><div class="section-head"><div><h2>Administrasi Donasi</h2><p>Klaim menunggu dan akun yang sudah terverifikasi.</p></div><button class="btn secondary" onclick="loadDonations()">Muat Ulang</button></div><div class="grid two"><div class="card"><h2 style="margin-top:0">Klaim Menunggu</h2><div id="donationClaims" class="claim-grid"></div></div><div class="card"><h2 style="margin-top:0">Akun Terverifikasi</h2><div id="donationVerified" class="claim-grid"></div></div></div><div id="donationKeyOutput"></div></section>

<section id="distribution" class="section" style="margin-top:14px"><div class="grid two"><div class="card"><h2 style="margin-top:0">Paket Distribusi eduXid</h2><p class="muted">Builder membuat COPY kerja di folder TEMP, membersihkan copy, memvalidasi .env/database, membuat ZIP + SHA-256, lalu mengaudit isi ZIP. Source asli tidak dibersihkan.</p><div class="field"><label>Root eduXidMaster</label><input id="rootPath" placeholder="C:\eduXidMaster"></div><button class="btn primary" onclick="buildDistribution()">Buat Paket Distribusi</button><p class="muted">Output: <b>DIST_ADMIN_PANEL</b> pada root yang dipilih.</p></div><div class="card"><h2 style="margin-top:0">Log Build</h2><div id="distOutput" class="output">Belum ada proses.</div></div></div></section>

<section id="deploy" class="section" style="margin-top:14px"><div class="grid three"><div class="card"><h2 style="margin-top:0">eduXid Cloud</h2><p class="muted">Jalankan deploy-cloud.cmd termasuk migration yang diperlukan.</p><button class="btn primary" onclick="runLocal('deploy_cloud','Deploy Cloud')">Deploy Worker Cloud</button></div><div class="card"><h2 style="margin-top:0">PWA Guru</h2><p class="muted">Auto-version SW/aset mengikuti mekanisme V9+.</p><button class="btn success" onclick="runLocal('deploy_guru','Deploy PWA Guru')">Deploy PWA Guru</button></div><div class="card"><h2 style="margin-top:0">PWA Siswa</h2><p class="muted">Deploy staging bersih dengan auto-version SW/aset.</p><button class="btn success" onclick="runLocal('deploy_siswa','Deploy PWA Siswa')">Deploy PWA Siswa</button></div></div><div class="card" style="margin-top:14px"><h2 style="margin-top:0">Log Deploy</h2><div id="deployOutput" class="output">Belum ada proses.</div></div></section>

<section id="security" class="section" style="margin-top:14px"><div class="grid two"><div class="card"><h2 style="margin-top:0">Generator Master Key</h2><p class="muted">Membuat key acak 256-bit di browser lokal. Tidak disimpan otomatis.</p><button class="btn secondary" onclick="generateMaster()">Buat Key Baru</button><div class="field" style="margin-top:12px"><label>Master Key Baru</label><input id="newMasterKey" type="password" autocomplete="off"></div><button class="btn danger" onclick="rotateMaster()">Rotasi EDUXID_ADMIN_KEY Worker</button></div><div class="card danger-zone"><h2 style="margin-top:0">Peringatan Keamanan</h2><p class="muted">Rotasi hanya dilakukan setelah key lama berhasil diverifikasi ke Cloud. Tindakan ini membutuhkan Wrangler lokal yang sudah login ke Cloudflare. Setelah sukses, panel akan menggunakan key baru pada sesi ini. Jangan distribusikan Master Key ke sekolah/GTK.</p><div id="securityStatus" class="status">Belum ada tindakan.</div></div></div></section>

<section id="diagnostic" class="section" style="margin-top:14px"><div class="grid two"><div class="card"><h2 style="margin-top:0">Diagnostik Lokal</h2><button class="btn secondary" onclick="loadLocalInfo()">Periksa Instalasi</button><div id="diagLocal" class="status" style="margin-top:10px">-</div></div><div class="card"><h2 style="margin-top:0">Diagnostik Cloud</h2><button class="btn secondary" onclick="loadSummary()">Periksa Cloud</button><div id="diagCloud" class="status" style="margin-top:10px">-</div></div></div></section>
</main></div>

<div id="schoolModal" class="modal"><div class="modal-panel"><div class="section-head"><div><h2 id="schoolModalTitle">Detail Sekolah</h2><p id="schoolModalSub"></p></div><button class="btn neutral" onclick="closeSchool()">Tutup</button></div><div class="tabs"><button class="active" data-sub="teachers">GTK</button><button data-sub="devices">Perangkat</button><button data-sub="students">Siswa</button><button data-sub="schoolkeys">Key</button><button data-sub="sync">Sinkronisasi</button><button data-sub="enrollment">Auto-Pair</button></div><div id="teachers" class="subpanel active"></div><div id="devices" class="subpanel"></div><div id="students" class="subpanel"></div><div id="schoolkeys" class="subpanel"></div><div id="sync" class="subpanel"></div><div id="enrollment" class="subpanel"></div></div></div>
<script>
(()=>{
const $=id=>document.getElementById(id), esc=v=>String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
let connected=false, currentSchool=null, localInfo=null;
const pageMeta={dashboard:['Dasbor Pusat','Status terpusat eduXid Cloud dan instalasi pusat.'],schools:['Sekolah & Akun Cloud','Sekolah, GTK, siswa, perangkat, dan sinkronisasi Cloud.'],keys:['Kunci Sekolah','Pembuatan dan pencabutan Cloud key sekolah.'],donation:['Administrasi Donasi','Verifikasi klaim dan status donasi secara terpusat.'],distribution:['Paket Distribusi','Build paket distribusi bersih dari copy yang aman.'],deploy:['Deploy Cloud & PWA','Deploy Worker, PWA Guru, dan PWA Siswa dari satu panel.'],security:['Keamanan / Master Key','Generator dan rotasi Master EDUXID_ADMIN_KEY.'],diagnostic:['Diagnostik','Pemeriksaan instalasi pusat dan koneksi Cloud.']};
function status(el,msg,kind=''){el.className='status'+(kind?' '+kind:'');el.textContent=msg}
async function call(action,payload={},needMaster=true){const master=$('masterKey').value.trim();if(needMaster&&!master)throw new Error('Master EDUXID_ADMIN_KEY wajib diisi.');const r=await fetch('bridge.php',{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json'},cache:'no-store',body:JSON.stringify({action,master_key:master,payload})});const raw=await r.text();let d;try{d=raw?JSON.parse(raw):{}}catch(_){throw new Error('Respons lokal bukan JSON: '+raw.slice(0,240))}if(!r.ok||d.success!==true)throw new Error(d?.error?.message||d?.message||`Permintaan gagal HTTP ${r.status}`);return d}
async function connect(){status($('globalStatus'),'Memverifikasi Master Key…');try{await call('auth_verify');connected=true;status($('globalStatus'),'Terhubung aman ke eduXid Cloud sebagai Master Admin.','ok');await refreshAll()}catch(e){connected=false;status($('globalStatus'),e.message,'err')}}
async function refreshAll(){await Promise.allSettled([loadSummary(),loadLocalInfo(),loadSchools(),loadKeys(),loadDonations()])}
function firstNumber(...values){for(const value of values){if(value!==undefined&&value!==null&&value!==''&&!Number.isNaN(Number(value)))return Number(value)}return null}
async function loadSummary(){try{const [d,schoolsResult]=await Promise.all([call('central_summary'),call('central_schools').catch(()=>null)]);const x=d.data||{};const schoolRows=schoolsResult?.data?.schools||[];let activeDevices=firstNumber(x.active_devices,x.active_device_count,x.devices_active,x.active_devices_count);let totalDevices=firstNumber(x.devices,x.device_count,x.total_devices,x.devices_total);if(activeDevices===null&&schoolRows.length)activeDevices=schoolRows.reduce((sum,row)=>sum+(firstNumber(row.active_device_count,row.active_devices,row.devices_active)||0),0);if(totalDevices===null&&schoolRows.length)totalDevices=schoolRows.reduce((sum,row)=>sum+(firstNumber(row.device_count,row.devices,row.total_devices)||0),0);activeDevices=activeDevices??0;totalDevices=totalDevices??0;const normalized={...x,active_devices:activeDevices,devices:totalDevices};$('stats').innerHTML=[['Sekolah',firstNumber(x.schools,x.school_count)??0],['GTK Cloud',firstNumber(x.teacher_accounts,x.teacher_count,x.gtk_count)??0],['Siswa Cloud',firstNumber(x.student_accounts,x.student_count)??0],['Perangkat Aktif',`${activeDevices}/${totalDevices}`],['Key Sekolah Aktif',firstNumber(x.active_school_keys,x.active_key_count)??0],['Sync Pending',firstNumber(x.pending_sync_events,x.pending_sync_count)??0],['Donatur Terverifikasi',firstNumber(x.verified_donations,x.verified_donation_count)??0],['Klaim Donasi',firstNumber(x.pending_donation_claims,x.pending_claim_count)??0]].map(([a,b])=>`<div class="stat"><span>${esc(a)}</span><b>${esc(b)}</b></div>`).join('');status($('cloudSummary'),`Cloud terhubung. Data diperbarui ${x.generated_at||'-'}.`,'ok');status($('diagCloud'),JSON.stringify(normalized,null,2),'ok')}catch(e){status($('cloudSummary'),e.message,'err');status($('diagCloud'),e.message,'err')}}
async function loadLocalInfo(){try{const root=$('rootPath')?.value.trim()||'';const d=await call('local_info',{root_path:root},false);localInfo=d.data;if($('rootPath')&&!$('rootPath').value)$('rootPath').value=d.data.root_path;const t=Object.entries(d.data).map(([k,v])=>`${k}: ${v}`).join('\n');status($('localSummary'),t,d.data.has_eduxid?'ok':'warn');status($('diagLocal'),t,d.data.has_eduxid?'ok':'warn')}catch(e){status($('localSummary'),e.message,'err');status($('diagLocal'),e.message,'err')}}
async function loadSchools(){if(!connected)return;try{const d=await call('central_schools');const items=d?.data?.schools||[];$('schoolsGrid').innerHTML=items.length?items.map(s=>`<div class="school"><h3>${esc(s.school_name||s.school_id)}</h3><p>NPSN ${esc(s.school_id)} · aktivitas ${esc(s.last_device_activity||'-')}</p><div class="metrics"><div><b>${esc(s.teacher_count)}</b><span>GTK</span></div><div><b>${esc(s.student_count)}</b><span>Siswa</span></div><div><b>${esc(s.active_device_count)}/${esc(s.device_count)}</b><span>Device</span></div><div><b>${esc(s.active_key_count)}</b><span>Key</span></div></div><div class="toolbar"><button class="btn primary" onclick="openSchool('${esc(s.school_id)}','${esc(String(s.school_name||'').replace(/'/g,"\\'"))}')">Kelola</button>${Number(s.pending_sync_count)>0?`<span class="pill red">${esc(s.pending_sync_count)} sync pending</span>`:'<span class="pill green">Sync normal</span>'}</div></div>`).join(''):'<div class="status">Belum ada sekolah terdaftar.</div>'}catch(e){$('schoolsGrid').innerHTML=`<div class="status err">${esc(e.message)}</div>`}}
async function openSchool(id,name){currentSchool=id;$('schoolModal').classList.add('open');$('schoolModalTitle').textContent=name||('Sekolah '+id);$('schoolModalSub').textContent='NPSN '+id;for(const x of ['teachers','devices','students','schoolkeys','sync','enrollment'])$(x).innerHTML='<div class="status">Memuat…</div>';try{const d=await call('central_school',{school_id:id});renderSchool(d.data||{})}catch(e){$('teachers').innerHTML=`<div class="status err">${esc(e.message)}</div>`}}
function closeSchool(){$('schoolModal').classList.remove('open')}
function table(headers,rows){return `<div class="table-wrap"><table class="table"><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`}
function assignmentCount(raw){try{const x=JSON.parse(raw||'[]');return Array.isArray(x)?x.filter(a=>!a?.scope_only).length:0}catch(_){return 0}}
function renderSchool(d){const teachers=d.teachers||[],students=d.students||[],devices=d.devices||[],keys=d.keys||[];$('teachers').innerHTML=table(['Nama','Login ID','Penugasan','Update'],teachers.map(t=>`<tr><td><b>${esc(t.name||'-')}</b></td><td>${esc(t.login_id)}</td><td>${assignmentCount(t.assignments)} penugasan</td><td>${esc(t.updated_at||'-')}</td></tr>`));$('students').innerHTML=table(['Nama','Login ID/NISN','Rombel','Update'],students.map(s=>`<tr><td><b>${esc(s.name||'-')}</b></td><td>${esc(s.login_id)}</td><td>${esc(s.homeroom_names||s.homeroom_key||'-')}</td><td>${esc(s.updated_at||'-')}</td></tr>`));$('devices').innerHTML=table(['Device','Tipe','Login','Status','Update','Aksi'],devices.map(v=>`<tr><td><code>${esc(v.device_id)}</code></td><td>${esc(v.device_type)}</td><td>${esc(v.login_id||'-')}</td><td><span class="pill ${v.status==='active'?'green':'red'}">${esc(v.status)}</span></td><td>${esc(v.updated_at||'-')}</td><td><div class="toolbar"><button class="btn secondary" onclick="resyncDevice('${esc(v.device_id)}')">Resync</button><button class="btn ${v.status==='active'?'danger':'success'}" onclick="setDeviceStatus('${esc(v.device_id)}','${v.status==='active'?'inactive':'active'}')">${v.status==='active'?'Nonaktifkan':'Aktifkan'}</button></div></td></tr>`));$('schoolkeys').innerHTML=table(['Key ID','Label','Status','Dibuat','Dipakai','Aksi'],keys.map(k=>`<tr><td><code>${esc(k.key_id)}</code></td><td>${esc(k.label||'-')}</td><td><span class="pill ${Number(k.is_active)===1?'green':'red'}">${Number(k.is_active)===1?'AKTIF':'DICABUT'}</span></td><td>${esc(k.created_at||'-')}</td><td>${esc(k.last_used_at||'-')}</td><td>${Number(k.is_active)===1?`<button class="btn danger" onclick="revokeKey('${esc(k.key_id)}')">Cabut</button>`:`<button class="btn danger" onclick="deleteKey('${esc(k.key_id)}')">Hapus Permanen</button>`}</td></tr>`));const stats=d.sync_stats||[];$('sync').innerHTML=`<div class="grid stats">${stats.map(x=>`<div class="stat"><span>${esc(x.status)}</span><b>${esc(x.total)}</b></div>`).join('')}</div>`;$('enrollment').innerHTML=`<div class="card"><h3 style="margin-top:0">Buat Enrollment / Auto-Pair</h3><div class="grid two"><div class="field"><label>Login ID GTK (opsional)</label><input id="enrLogin" placeholder="Kosong = umum"></div><div class="field"><label>Berlaku sampai ISO (opsional)</label><input id="enrExpiry" placeholder="2026-12-31T23:59:59+07:00"></div></div><button class="btn primary" onclick="createEnrollment()">Buat Enrollment Code</button><div id="enrOutput"></div></div>`}
async function resyncDevice(id){try{const d=await call('device_resync',{device_id:id});alert(`Resync dijadwalkan. Event: ${d?.data?.requeued_events??0}`)}catch(e){alert(e.message)}}
async function setDeviceStatus(id,st){if(!confirm(`${st==='inactive'?'Nonaktifkan':'Aktifkan'} perangkat ${id}?`))return;try{await call('device_status',{device_id:id,status:st});await openSchool(currentSchool,$('schoolModalTitle').textContent)}catch(e){alert(e.message)}}
async function createEnrollment(){try{const login=$('enrLogin').value.trim(),expires=$('enrExpiry').value.trim();const d=await call('enrollment_create',{school_id:currentSchool,login_id:login||null,max_uses:login?1:0,expires_at:expires||null});$('enrOutput').innerHTML=`<div class="keybox"><div>ENROLLMENT CODE</div><code>${esc(d.data.enrollment_code)}</code><button class="btn secondary" style="margin-top:8px" onclick="navigator.clipboard.writeText('${esc(d.data.enrollment_code)}')">Salin</button></div>`}catch(e){$('enrOutput').innerHTML=`<div class="status err">${esc(e.message)}</div>`}}
async function loadKeys(){if(!connected)return;try{const d=await call('keys_list');const items=d?.data?.keys||[];$('keysTable').innerHTML=table(['NPSN','Label','Key ID','Status','Dibuat','Terakhir Dipakai','Aksi'],items.map(k=>`<tr><td>${esc(k.school_id)}</td><td>${esc(k.label||'-')}</td><td><code>${esc(k.key_id)}</code></td><td><span class="pill ${Number(k.is_active)===1?'green':'red'}">${Number(k.is_active)===1?'AKTIF':'DICABUT'}</span></td><td>${esc(k.created_at||'-')}</td><td>${esc(k.last_used_at||'-')}</td><td>${Number(k.is_active)===1?`<button class="btn danger" onclick="revokeKey('${esc(k.key_id)}')">Cabut Akses</button>`:`<button class="btn danger" onclick="deleteKey('${esc(k.key_id)}')">Hapus Permanen</button>`}</td></tr>`))}catch(e){$('keysTable').innerHTML=`<div class="status err">${esc(e.message)}</div>`}}
async function createSchoolKey(){const school=$('keySchool').value.trim(),label=$('keyLabel').value.trim();if(!school)return alert('NPSN wajib diisi.');if(!confirm(`Buat key pair Cloud untuk ${school}? Plaintext token hanya tampil sekali.`))return;try{const d=await call('keys_create',{school_id:school,label});$('newKeyBox').innerHTML=`<div class="keybox"><div>ADMIN TOKEN — SIMPAN SEKARANG</div><code>${esc(d.data.admin_token)}</code><div style="margin-top:8px">Key ID: ${esc(d.data.key_id)}</div><button class="btn secondary" style="margin-top:8px" onclick="navigator.clipboard.writeText('${esc(d.data.admin_token)}')">Salin Token</button></div>`;await Promise.all([loadKeys(),loadSchools()])}catch(e){alert(e.message)}}
async function revokeKey(id){if(!confirm(`Cabut key ${id}? Sekolah yang memakai key ini akan ditolak Cloud.`))return;try{await call('keys_revoke',{key_id:id});await Promise.all([loadKeys(),loadSchools()]);if(currentSchool)await openSchool(currentSchool,$('schoolModalTitle').textContent)}catch(e){alert(e.message)}}
async function deleteKey(id){if(!confirm(`HAPUS PERMANEN key ${id}? Tindakan ini hanya diizinkan jika key sudah dicabut dan akan menghapus record key dari Cloud.`))return;try{await call('keys_delete',{key_id:id});await Promise.all([loadKeys(),loadSchools()]);if(currentSchool)await openSchool(currentSchool,$('schoolModalTitle').textContent)}catch(e){alert(e.message)}}
function waDigits(v){return String(v||'').replace(/\D/g,'')}
function showDonationKey(d){const key=String(d.verification_key||'');const wa=waDigits(d.whatsapp);const msg=`Halo ${d.donor_name||'Pengguna eduXid'}, kode verifikasi donasi eduXid Anda: ${key}. Masukkan kode ini pada halaman/jendela Donasi eduXid.`;$('donationKeyOutput').innerHTML=`<div class="keybox"><div>KODE VERIFIKASI</div><code>${esc(key)}</code><div class="toolbar" style="margin-top:8px"><button class="btn secondary" onclick="navigator.clipboard.writeText('${esc(key)}')">Salin</button>${wa?`<a class="btn success" target="_blank" rel="noopener" href="https://wa.me/${encodeURIComponent(wa)}?text=${encodeURIComponent(msg)}">Kirim WhatsApp</a>`:''}</div></div>`}
async function loadDonations(){if(!connected)return;try{const [a,b]=await Promise.all([call('donation_claims'),call('donation_verified')]);const claims=a?.data?.claims||[],verified=b?.data?.accounts||[];$('donationClaims').innerHTML=claims.length?claims.map(c=>`<div class="claim"><h3>${esc(c.donor_name||c.login_id)}</h3><p>NPSN ${esc(c.school_id)} · ${esc(c.login_id)}</p><div class="meta"><div>WA: ${esc(c.whatsapp||'-')}</div><div>${esc(String(c.channel||'').toUpperCase())} · ${esc(c.amount||'-')}</div><div>Ref: ${esc(c.transaction_ref||'-')}</div><div>${esc(c.created_at||'-')}</div></div><div class="toolbar"><button class="btn primary" onclick="approveDonation('${esc(c.claim_id)}')">Verifikasi & Buat Kode</button><button class="btn danger" onclick="rejectDonation('${esc(c.claim_id)}')">Tolak</button></div></div>`).join(''):'<div class="status ok">Tidak ada klaim menunggu.</div>';$('donationVerified').innerHTML=verified.length?verified.map(a=>`<div class="claim"><h3>${esc(a.donor_name||a.login_id)}</h3><p>NPSN ${esc(a.school_id)} · ${esc(a.login_id)}</p><div class="meta"><div>WA: ${esc(a.whatsapp||'-')}</div><div>Verified: ${esc(a.verified_at||'-')}</div><div>${esc(String(a.channel||'-').toUpperCase())}</div><div>Ref: ${esc(a.transaction_ref||'-')}</div></div><div class="toolbar"><button class="btn secondary" onclick="restoreDonationKey('${esc(a.school_id)}','${esc(a.login_id)}')">Pulihkan Key</button><button class="btn danger" onclick="deleteDonation('${esc(a.school_id)}','${esc(a.login_id)}')">Hapus Status</button></div></div>`).join(''):'<div class="status">Belum ada akun terverifikasi.</div>'}catch(e){$('donationClaims').innerHTML=`<div class="status err">${esc(e.message)}</div>`}}
async function approveDonation(id){try{const d=await call('donation_approve',{claim_id:id});showDonationKey(d.data||{});await loadDonations()}catch(e){alert(e.message)}}
async function rejectDonation(id){if(!confirm('Tolak klaim ini?'))return;try{await call('donation_reject',{claim_id:id});await loadDonations()}catch(e){alert(e.message)}}
async function restoreDonationKey(s,l){if(!confirm('Buat key pengganti baru? Key lama yang belum dipakai akan dibatalkan.'))return;try{const d=await call('donation_restore_key',{school_id:s,login_id:l});showDonationKey(d.data||{})}catch(e){alert(e.message)}}
async function deleteDonation(s,l){if(!confirm('Hapus status verifikasi donasi? Akun eduXid tidak dihapus dan reminder akan muncul kembali.'))return;try{await call('donation_delete',{school_id:s,login_id:l});await loadDonations()}catch(e){alert(e.message)}}
async function buildDistribution(){if(!confirm('Buat paket distribusi dari COPY aman? Proses dapat memerlukan beberapa menit.'))return;const root=$('rootPath').value.trim();$('distOutput').textContent='Memproses…';try{const d=await call('build_distribution',{root_path:root});$('distOutput').textContent=d?.data?.output||'Selesai.'}catch(e){$('distOutput').textContent=e.message}}
async function runLocal(action,label){const root=$('rootPath').value.trim();if(!confirm(`${label}?`))return;$('deployOutput').textContent=`${label} sedang berjalan…`;try{const d=await call(action,{root_path:root});$('deployOutput').textContent=d?.data?.output||`${label} selesai.`}catch(e){$('deployOutput').textContent=e.message}}
function generateMaster(){const a=new Uint8Array(32);crypto.getRandomValues(a);$('newMasterKey').value=[...a].map(b=>b.toString(16).padStart(2,'0')).join('')}
async function rotateMaster(){const root=$('rootPath').value.trim(),newKey=$('newMasterKey').value.trim();if(newKey.length<32)return alert('Buat/isi key baru minimal 32 karakter.');if(!confirm('ROTASI MASTER KEY WORKER? Key lama akan langsung tidak berlaku setelah rotasi sukses.'))return;status($('securityStatus'),'Menjalankan rotasi Worker secret…');try{const d=await call('rotate_master',{root_path:root,new_master_key:newKey});$('masterKey').value=newKey;status($('securityStatus'),d.message||'Rotasi sukses.','ok');await connect()}catch(e){status($('securityStatus'),e.message,'err')}}

document.querySelectorAll('.nav button').forEach(b=>b.onclick=()=>{document.querySelectorAll('.nav button').forEach(x=>x.classList.remove('active'));b.classList.add('active');document.querySelectorAll('.section').forEach(x=>x.classList.remove('active'));$(b.dataset.page).classList.add('active');$('pageTitle').textContent=pageMeta[b.dataset.page][0];$('pageDesc').textContent=pageMeta[b.dataset.page][1]});
document.querySelectorAll('.tabs button').forEach(b=>b.onclick=()=>{document.querySelectorAll('.tabs button').forEach(x=>x.classList.remove('active'));b.classList.add('active');document.querySelectorAll('.subpanel').forEach(x=>x.classList.remove('active'));$(b.dataset.sub).classList.add('active')});
$('connectBtn').onclick=connect;$('masterKey').addEventListener('keydown',e=>{if(e.key==='Enter')connect()});$('schoolModal').addEventListener('click',e=>{if(e.target===$('schoolModal'))closeSchool()});loadLocalInfo();
window.openSchool=openSchool;window.closeSchool=closeSchool;window.refreshAll=refreshAll;window.loadSchools=loadSchools;window.loadKeys=loadKeys;window.loadDonations=loadDonations;window.loadLocalInfo=loadLocalInfo;window.loadSummary=loadSummary;window.createSchoolKey=createSchoolKey;window.revokeKey=revokeKey;window.deleteKey=deleteKey;window.resyncDevice=resyncDevice;window.setDeviceStatus=setDeviceStatus;window.createEnrollment=createEnrollment;window.approveDonation=approveDonation;window.rejectDonation=rejectDonation;window.restoreDonationKey=restoreDonationKey;window.deleteDonation=deleteDonation;window.buildDistribution=buildDistribution;window.runLocal=runLocal;window.generateMaster=generateMaster;window.rotateMaster=rotateMaster;
})();
</script>
</body></html>
